/**
 * Evidence-backed GLLib BSprite frame drawing helpers for Green Farm 3.
 * The source frame manifest is generated by joining original /10 and /9 records
 * to original /5 BSprite metadata; image modules are decoded from the JAR.
 */

export const MIDP_ANCHOR = Object.freeze({
  HCENTER: 1,
  VCENTER: 2,
  LEFT: 4,
  RIGHT: 8,
  TOP: 16,
  BOTTOM: 32,
  BASELINE: 64,
});

export function s8(value) {
  const byte = value & 0xff;
  return byte > 0x7f ? byte - 0x100 : byte;
}

// Port of d.java:2261-2267: GLLib FModule orientation to MIDP Sprite.TRANS_*.
const F_MODULE_TO_MIDP = Object.freeze([0, 2, 1, 3, 5, 7, 4, 6]);
const MIRROR_HORIZONTAL = Object.freeze([1, 0, 3, 2, 6, 7, 4, 5]);
const MIRROR_VERTICAL = Object.freeze([2, 3, 0, 1, 5, 4, 7, 6]);
const ROTATE_90 = Object.freeze([4, 5, 6, 7, 3, 2, 1, 0]);

// Port of d.java:1823-1835: compose source flips/rotation and adjust signed offsets.
export function resolveFModuleTransform(fmoduleFlags, frameTransform, x, y, width, height) {
  if (!Number.isInteger(fmoduleFlags) || fmoduleFlags < 0 || fmoduleFlags > 255) {
    throw new RangeError(`Invalid source FModule flags: ${fmoduleFlags}`);
  }
  if (fmoduleFlags & ~0x0f) throw new RangeError(`Unknown image FModule flag bits: 0x${fmoduleFlags.toString(16)}`);
  if (!Number.isInteger(frameTransform) || (frameTransform & ~7) !== 0) {
    throw new RangeError(`Invalid source frame transform: ${frameTransform}`);
  }

  let orientation = fmoduleFlags & 0xf;
  if (orientation > 7) throw new RangeError(`Unknown source FModule orientation: ${orientation}`);
  let moduleWidth = orientation & 4 ? height : width;
  let moduleHeight = orientation & 4 ? width : height;
  let offsetX = x;
  let offsetY = y;
  if (frameTransform & 1) {
    orientation = MIRROR_HORIZONTAL[orientation];
    offsetX = -offsetX - moduleWidth;
  }
  if (frameTransform & 2) {
    orientation = MIRROR_VERTICAL[orientation];
    offsetY = -offsetY - moduleHeight;
  }
  if (frameTransform & 4) {
    orientation = ROTATE_90[orientation];
    const previousX = offsetX;
    offsetX = -offsetY - moduleHeight;
    offsetY = previousX;
    [moduleWidth, moduleHeight] = [moduleHeight, moduleWidth];
  }
  return {
    transform: F_MODULE_TO_MIDP[orientation],
    offsetX,
    offsetY,
    width: moduleWidth,
    height: moduleHeight,
  };
}

/**
 * Canvas equivalent of javax.microedition.lcdui.Graphics.drawRegion.
 * transform is the MIDP Sprite.TRANS_* value, not a BSprite module type.
 */
// Port of f.java:657-674 (MIDP drawRegion wrapper); anchor semantics follow MIDP.
export function drawRegionMIDP(ctx, image, sx, sy, sw, sh, transform, x, y, anchor = 20) {
  if (!Number.isInteger(transform) || transform < 0 || transform > 7) {
    throw new RangeError(`Invalid MIDP Sprite transform: ${transform}`);
  }
  const rotated = (transform & 4) !== 0;
  const dw = rotated ? sh : sw;
  const dh = rotated ? sw : sh;
  let dx = x;
  let dy = y;

  if (anchor & MIDP_ANCHOR.HCENTER) dx -= dw >> 1;
  else if (anchor & MIDP_ANCHOR.RIGHT) dx -= dw;
  if (anchor & MIDP_ANCHOR.VCENTER) dy -= dh >> 1;
  else if (anchor & MIDP_ANCHOR.BOTTOM) dy -= dh;

  ctx.imageSmoothingEnabled = false;
  if (transform === 0) {
    ctx.drawImage(image, sx, sy, sw, sh, dx, dy, sw, sh);
    return { x: dx, y: dy, width: sw, height: sh };
  }

  ctx.save();
  ctx.translate(dx + dw / 2, dy + dh / 2);
  switch (transform) {
    case 1: ctx.rotate(Math.PI); ctx.scale(-1, 1); break; // MIRROR_ROT180
    case 2: ctx.scale(-1, 1); break; // MIRROR
    case 3: ctx.rotate(Math.PI); break; // ROT180
    case 4: ctx.rotate(-Math.PI / 2); ctx.scale(-1, 1); break; // MIRROR_ROT270
    case 5: ctx.rotate(Math.PI / 2); break; // ROT90
    case 6: ctx.rotate(-Math.PI / 2); break; // ROT270
    case 7: ctx.rotate(Math.PI / 2); ctx.scale(-1, 1); break; // MIRROR_ROT90
    default: throw new RangeError(`Invalid MIDP Sprite transform: ${transform}`);
  }
  ctx.drawImage(image, sx, sy, sw, sh, -sw / 2, -sh / 2, sw, sh);
  ctx.restore();
  return { x: dx, y: dy, width: dw, height: dh };
}

/** Execute a draw pass inside a MIDP clip rectangle. */
// Port of f.java:617-626 (setClip/clipRect wrappers).
export function withMIDPClip(ctx, x, y, width, height, draw) {
  ctx.save();
  ctx.beginPath();
  ctx.rect(x, y, width, height);
  ctx.clip();
  try {
    return draw();
  } finally {
    ctx.restore();
  }
}

/** Compose source FModules at the caller's source coordinate. */
// Port of d.java:1796-1855: frame drawing uses the supplied origin and FModule offsets.
export function drawBSpriteFrame(ctx, frameRecord, moduleImages, x, y, frameTransform = 0, clipRect = null) {
  if (!frameRecord || !Array.isArray(frameRecord.frame_modules)) {
    throw new TypeError('Missing verified BSprite frame module records');
  }
  if (!Number.isInteger(frameTransform) || frameTransform < 0 || frameTransform > 7) {
    throw new RangeError(`Invalid source frame transform: ${frameTransform}`);
  }
  const draw = () => {
    for (const part of frameRecord.frame_modules) {
      if (part.flags & 0x10) {
        throw new RangeError('Source FModule selects a procedural/shape module; image path cannot draw it');
      }
      const image = moduleImages.get(part.module_png);
      if (!image) throw new Error(`Missing decoded BSprite module: ${part.module_png}`);
      const expected = part.module;
      if (image.width !== expected.w || image.height !== expected.h) {
        throw new RangeError(`Source module dimensions disagree: ${part.module_png}`);
      }
      const resolved = resolveFModuleTransform(part.flags, frameTransform, part.offset_x, part.offset_y, expected.w, expected.h);
      drawRegionMIDP(
        ctx,
        image,
        0,
        0,
        expected.w,
        expected.h,
        resolved.transform,
        x + resolved.offsetX,
        y + resolved.offsetY,
        MIDP_ANCHOR.LEFT | MIDP_ANCHOR.TOP,
      );
    }
    return { x, y, width: frameRecord.frame_bounds?.width ?? null, height: frameRecord.frame_bounds?.height ?? null };
  };
  if (clipRect) return withMIDPClip(ctx, clipRect.x, clipRect.y, clipRect.width, clipRect.height, draw);
  return draw();
}

// Port of d.java:1796-1855 and i.java:661-785: render each source tile frame
// row-major at its exact map pitch; only the caller's viewport provides clipping.
export function drawBSpriteTileMap(ctx, tileMap, sprite, moduleImages, { x = 0, y = 0, width = 240, height = 320, cameraX = 0, cameraY = 0 } = {}) {
  if (!tileMap || !sprite || !Array.isArray(sprite.frames)) throw new TypeError('Missing source tilemap or BSprite frame table');
  if (tileMap.tileIds.length !== tileMap.width * tileMap.height || tileMap.attributes.length !== tileMap.tileIds.length) {
    throw new RangeError('Source tile-map planes do not match dimensions');
  }
  return withMIDPClip(ctx, x, y, width, height, () => {
    let drawn = 0;
    for (let row = 0; row < tileMap.height; row += 1) {
      for (let column = 0; column < tileMap.width; column += 1) {
        const cell = row * tileMap.width + column;
        const frameIndex = tileMap.tileIds[cell];
        if (frameIndex === 0xff) continue;
        const frame = sprite.frames[frameIndex];
        if (!frame) throw new RangeError(`Source tile ${frameIndex} has no frame`);
        const startX = x + column * tileMap.tileWidth - cameraX;
        const startY = y + row * tileMap.tileHeight - cameraY;
        for (let p = 0; p < frame.fmoduleCount; p += 1) {
          const fmodule = sprite.fmodules[frame.firstFmodule + p];
          const module = sprite.modules[fmodule.moduleIndex];
          if (!module) throw new RangeError(`Tile frame ${frameIndex} references a missing module`);
          const resolved = resolveFModuleTransform(fmodule.flags, tileMap.attributes[cell] & 7,
            fmodule.offsetX, fmodule.offsetY, module.width ?? 0, module.height ?? 0);
          if (module.type === 0) {
            const image = moduleImages[fmodule.moduleIndex];
            if (!image) throw new Error(`Missing source tile module ${fmodule.moduleIndex}`);
            drawRegionMIDP(ctx, image, 0, 0, module.width, module.height,
              resolved.transform, startX + resolved.offsetX, startY + resolved.offsetY, MIDP_ANCHOR.LEFT | MIDP_ANCHOR.TOP);
          } else if (module.type === 0xfe && (fmodule.flags & 0x10) === 0) {
            // Port of d.java:1903-1923: module type FE is a source solid rectangle.
            // Expand by +0.6px to prevent sub-pixel hairline seams when worldZoom != 1.0.
            const color = module.colorOrParameter >>> 0;
            const alpha = color >>> 24;
            if (alpha === 0xff || alpha === 0) {
              ctx.fillStyle = `#${(color & 0xffffff).toString(16).padStart(6, '0')}`;
              ctx.fillRect(startX + resolved.offsetX, startY + resolved.offsetY, resolved.width + 0.6, resolved.height + 0.6);
            }
          } else if (module.type === 0xfd) {
            // Port of d.java:252-257, 1934-1958: marker modules have no source draw operation.
            continue;
          } else {
            throw new RangeError(`Unsupported source tile module type 0x${module.type.toString(16)} / FModule flags 0x${fmodule.flags.toString(16)}`);
          }
        }
        drawn += 1;
      }
    }
    return { drawn, width: tileMap.width, height: tileMap.height, cameraX, cameraY };
  });
}

/** Load one source-generated frame manifest and its decoded original modules. */
// Source-data join: a.java:1979-1985, a.java:18029-18082, e.java:2981-2997.
export async function loadSourceFrame({ manifestUrl, moduleBaseUrl }) {
  const response = await fetch(manifestUrl);
  if (!response.ok) throw new Error(`Cannot load BSprite manifest (${response.status})`);
  const manifest = await response.json();
  if (!Array.isArray(manifest.frame_modules) || manifest.frame_modules.length === 0) {
    throw new TypeError('BSprite manifest has no frame modules');
  }

  const moduleImages = new Map();
  await Promise.all(manifest.frame_modules.map(async (part) => {
    if (part.module?.type !== 0) throw new RangeError('Non-image source module is unsupported');
    const image = new Image();
    const loaded = new Promise((resolve, reject) => {
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error(`Cannot load source module ${part.module_png}`));
    });
    image.src = new URL(part.module_png, moduleBaseUrl).href;
    moduleImages.set(part.module_png, await loaded);
  }));
  return { manifest, moduleImages };
}

/**
 * Draw any decoded /5 BSprite block frame at world/screen position (x, y).
 * Port of d.java:1796-1855 (BSprite.paintFrame): iterates fmodules of frames[frameIndex],
 * applies resolveFModuleTransform and drawRegionMIDP for image modules (type 0)
 * and solid rectangles (type 0xFE), skipping markers (type 0xFD).
 */
export function drawBSpriteBlockFrame(ctx, sprite, moduleImages, frameIndex, x, y, frameTransform = 0, skipModuleIndices = null) {
  if (!sprite || !Array.isArray(sprite.frames) || sprite.frames.length === 0) return null;
  const idx = Math.max(0, Math.min(sprite.frames.length - 1, frameIndex | 0));
  const frame = sprite.frames[idx];
  if (!frame) return null;
  for (let p = 0; p < frame.fmoduleCount; p += 1) {
    const fmodule = sprite.fmodules[frame.firstFmodule + p];
    if (!fmodule) continue;
    if (skipModuleIndices && skipModuleIndices.has(fmodule.moduleIndex)) continue;
    // Skip procedural / hyperframe flag 0x10 if encountered on non-image layers
    if (fmodule.flags & 0x10) continue;
    const module = sprite.modules[fmodule.moduleIndex];
    if (!module) continue;
    if (module.type === 0xfd) continue;
    const resolved = resolveFModuleTransform(
      fmodule.flags & 0x0f,
      frameTransform & 7,
      fmodule.offsetX,
      fmodule.offsetY,
      module.width ?? 0,
      module.height ?? 0,
    );
    if (module.type === 0) {
      const image = moduleImages[fmodule.moduleIndex];
      if (!image) continue;
      drawRegionMIDP(
        ctx,
        image,
        0,
        0,
        module.width,
        module.height,
        resolved.transform,
        Math.round(x + resolved.offsetX),
        Math.round(y + resolved.offsetY),
        MIDP_ANCHOR.LEFT | MIDP_ANCHOR.TOP,
      );
    } else if (module.type === 0xfe) {
      const color = module.colorOrParameter >>> 0;
      const alpha = color >>> 24;
      const rgb = color & 0xffffff;
      // Skip pure-white 0xFE clipping/mask rectangles used by GLLib /7 UI frames (a.java:9909)
      if (rgb !== 0xffffff) {
        const r = (rgb >>> 16) & 255;
        const g = (rgb >>> 8) & 255;
        const b = rgb & 255;
        ctx.fillStyle = (alpha === 0xff || alpha === 0)
          ? `rgb(${r},${g},${b})`
          : `rgba(${r},${g},${b},${(alpha / 255).toFixed(3)})`;
        ctx.fillRect(
          Math.round(x + resolved.offsetX),
          Math.round(y + resolved.offsetY),
          resolved.width,
          resolved.height,
        );
      }
    }
  }
  return sprite.bounds?.[idx] ?? null;
}

/**
 * Draw an animated frame from a decoded /5 BSprite block using its animations table.
 * Port of i.java:430-475 & d.java:1780-1795 (paintAFrame):
 * animations[i] = { frameCount, firstAnimationFrame }
 * animationFrames[k] = [frameIndex, duration, offsetX_s8, offsetY_s8, flags]
 */
export function drawBSpriteBlockAnim(ctx, sprite, moduleImages, animIndex, tick, x, y, frameTransform = 0) {
  if (!sprite || !Array.isArray(sprite.animations) || sprite.animations.length === 0) {
    return drawBSpriteBlockFrame(ctx, sprite, moduleImages, 0, x, y, frameTransform);
  }
  const aIdx = Math.max(0, Math.min(sprite.animations.length - 1, animIndex | 0));
  const anim = sprite.animations[aIdx];
  const count = anim?.frameCount ?? 0;
  const first = anim?.firstAnimationFrame ?? 0;
  if (!anim || count <= 0 || !Array.isArray(sprite.animationFrames)) {
    return drawBSpriteBlockFrame(ctx, sprite, moduleImages, 0, x, y, frameTransform);
  }
  // Sum source aframe durations so animations play at authentic GLLib cadence
  let totalDur = 0;
  for (let i = 0; i < count; i += 1) {
    const af = sprite.animationFrames[first + i];
    totalDur += Math.max(1, af ? af[1] : 1);
  }
  let pos = Math.floor(tick) % Math.max(1, totalDur);
  let chosen = sprite.animationFrames[first];
  for (let i = 0; i < count; i += 1) {
    const af = sprite.animationFrames[first + i];
    const dur = Math.max(1, af ? af[1] : 1);
    if (pos < dur) {
      chosen = af;
      break;
    }
    pos -= dur;
  }
  if (!chosen) return drawBSpriteBlockFrame(ctx, sprite, moduleImages, 0, x, y, frameTransform);
  const frameIndex = chosen[0];
  const offX = s8(chosen[2]);
  const offY = s8(chosen[3]);
  const aFlags = chosen[4] & 7;
  const combinedTransform = ((frameTransform & 7) ^ aFlags) & 7;
  const dx = (frameTransform & 1) ? -offX : offX;
  const dy = (frameTransform & 2) ? -offY : offY;
  return drawBSpriteBlockFrame(
    ctx,
    sprite,
    moduleImages,
    frameIndex,
    x + dx,
    y + dy,
    combinedTransform,
  );
}

const scaledFrameCache = new WeakMap();

/**
 * Draw any decoded /5 or /7 BSprite frame proportionally scaled & centered inside a (maxW x maxH) UI box.
 * Composites multi-module frames onto a 1:1 scratch canvas before scaling so fractional scales never
 * produce 1px seams between adjacent fmodules (e.g. /7[7] Quest portraits).
 */
export function drawBSpriteBlockFrameScaled(ctx, sprite, moduleImages, frameIndex, cx, cy, maxW, maxH) {
  if (!sprite || !Array.isArray(sprite.frames) || sprite.frames.length === 0) return;
  const idx = Math.max(0, Math.min(sprite.frames.length - 1, frameIndex | 0));
  const b = sprite.bounds?.[idx];
  const bw = Math.max(1, b?.width || 32);
  const bh = Math.max(1, b?.height || 32);
  const bx = b?.x ?? -(bw >> 1);
  const by = b?.y ?? -(bh >> 1);
  const scale = Math.min(1, maxW / bw, maxH / bh);

  if (typeof document !== 'undefined' && scale < 0.999) {
    let byIdx = scaledFrameCache.get(sprite);
    if (!byIdx) {
      byIdx = new Map();
      scaledFrameCache.set(sprite, byIdx);
    }
    let scratch = byIdx.get(idx);
    if (!scratch) {
      scratch = document.createElement('canvas');
      scratch.width = bw;
      scratch.height = bh;
      const sctx = scratch.getContext('2d');
      sctx.imageSmoothingEnabled = false;
      drawBSpriteBlockFrame(sctx, sprite, moduleImages, idx, -bx, -by, 0);
      byIdx.set(idx, scratch);
    }
    const dw = Math.max(1, Math.round(bw * scale));
    const dh = Math.max(1, Math.round(bh * scale));
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(scratch, 0, 0, bw, bh, Math.round(cx - dw / 2), Math.round(cy - dh / 2), dw, dh);
    return;
  }

  ctx.save();
  ctx.translate(Math.round(cx), Math.round(cy));
  ctx.scale(scale, scale);
  drawBSpriteBlockFrame(ctx, sprite, moduleImages, idx, -(bx + bw / 2), -(by + bh / 2), 0);
  ctx.restore();
}

/**
 * Render an original Green Farm 3 UI screen decoded from pack /6 using /7 & /5 BSprite blocks.
 * Port of a.java:9553-9621 (a.M(int n)) and a.java:9881-9958 (case 205 BSprite widget).
 */
export function drawOriginalUIScreen(ctx, widgets, getSpriteEntry, { filterWidget = null, maxX = 260, maxY = 340 } = {}) {
  if (!Array.isArray(widgets)) return 0;
  let drawn = 0;
  for (const w of widgets) {
    if (!w.visible) continue;
    if (filterWidget && !filterWidget(w)) continue;
    if (w.x > maxX || w.y > maxY || w.x < -120 || w.y < -80) continue;
    if (w.type === 201) {
      ctx.strokeStyle = `rgb(${w.r},${w.g},${w.b})`;
      ctx.strokeRect(w.x + 0.5, w.y + 0.5, w.w, w.h);
      drawn += 1;
    } else if (w.type === 202 && w.alpha > 0) {
      ctx.fillStyle = w.alpha >= 255
        ? `rgb(${w.r},${w.g},${w.b})`
        : `rgba(${w.r},${w.g},${w.b},${(w.alpha / 255).toFixed(3)})`;
      ctx.fillRect(w.x, w.y, w.w, w.h);
      drawn += 1;
    } else if (w.type === 205) {
      if (w.spriteId < 0 || w.frameIndex >= 255) continue;
      const pal = w.usePalette ? w.paletteIndex : 0;
      const entry = getSpriteEntry(w.spriteId, pal);
      if (!entry) continue;
      // Port of a.java:9998: case 205 always passes frameTransform = 0 (sArray[7] is not a rotation flag)
      drawBSpriteBlockFrame(ctx, entry.sprite, entry.moduleImages, w.frameIndex, w.x, w.y, 0);
      drawn += 1;
    }
  }
  return drawn;
}
